  'luz': '光',
  'ikay': '紋',
  'chrome-local-ai': '内',
  'quien-canta-hoy': '歌',
  'streetcai': '遊',
  'ares-api': '譜',
  'toolbar-aem': '替',
  'accesibilidad': '皆',
  'libros-del-mundo': '旅',
  'string-transformer': '変',
